use std::fs

struct Tree {
    keys: Vec<int>,
    lc: Vec<int>,
    rc: Vec<int>,
    root: int,
}

impl Tree {
    fn contains(self, x: int) -> bool {
        let mut cur = self.root
        while cur >= 0 {
            let k = self.keys[cur as usize]
            if x == k { return true }
            if x < k { cur = self.lc[cur as usize] } else { cur = self.rc[cur as usize] }
        }
        false
    }

    fn insert(self, x: int) -> bool {
        if self.contains(x) { return false }
        let id = self.keys.len() as int
        self.keys.push(x)
        self.lc.push(-1)
        self.rc.push(-1)
        if self.root < 0 {
            self.root = id
            return true
        }
        let mut cur = self.root
        loop {
            let k = self.keys[cur as usize]
            if x < k {
                let l = self.lc[cur as usize]
                if l < 0 { self.lc[cur as usize] = id
                    break }
                cur = l
            } else {
                let r = self.rc[cur as usize]
                if r < 0 { self.rc[cur as usize] = id
                    break }
                cur = r
            }
        }
        true
    }

    fn replace_child(self, parent: int, old: int, new: int) {
        if parent < 0 {
            self.root = new
        } else if self.lc[parent as usize] == old {
            self.lc[parent as usize] = new
        } else {
            self.rc[parent as usize] = new
        }
    }

    fn delete(self, x: int) -> bool {
        let mut parent = -1
        let mut cur = self.root
        while cur >= 0 {
            let k = self.keys[cur as usize]
            if x == k { break }
            parent = cur
            if x < k { cur = self.lc[cur as usize] } else { cur = self.rc[cur as usize] }
        }
        if cur < 0 { return false }
        let l = self.lc[cur as usize]
        let r = self.rc[cur as usize]
        if l < 0 {
            self.replace_child(parent, cur, r)
        } else if r < 0 {
            self.replace_child(parent, cur, l)
        } else {
            let mut sp = cur
            let mut s = r
            while self.lc[s as usize] >= 0 {
                sp = s
                s = self.lc[s as usize]
            }
            self.keys[cur as usize] = self.keys[s as usize]
            let sr = self.rc[s as usize]
            self.replace_child(sp, s, sr)
        }
        true
    }

    fn walk(self, n: int, out: Vec<int>) -> Vec<int> {
        let mut o = out
        if n < 0 { return o }
        o = self.walk(self.lc[n as usize], o)
        o.push(self.keys[n as usize])
        o = self.walk(self.rc[n as usize], o)
        o
    }

    fn h(self, n: int) -> int {
        if n < 0 { return 0 }
        let a = self.h(self.lc[n as usize])
        let b = self.h(self.rc[n as usize])
        if a > b { a + 1 } else { b + 1 }
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], lc: [], rc: [], root: -1 }
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if parts.len() == 0 { continue }
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.insert(x) { println("ok") } else { println("dup") }
        } else if cmd == "contains" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.contains(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.delete(x) { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            let v = t.walk(t.root, [])
            if v.len() == 0 {
                println("<empty>")
            } else {
                let mut s = ""
                let mut first = true
                for k in v {
                    if !first { s = s + " " }
                    first = false
                    s = s + "${k}"
                }
                println(s)
            }
        } else if cmd == "height" {
            println("${t.h(t.root)}")
        } else if cmd == "min" || cmd == "max" {
            if t.root < 0 {
                println("empty")
            } else {
                let mut c = t.root
                if cmd == "min" {
                    while t.lc[c as usize] >= 0 { c = t.lc[c as usize] }
                } else {
                    while t.rc[c as usize] >= 0 { c = t.rc[c as usize] }
                }
                println("${t.keys[c as usize]}")
            }
        }
    }
}

